    "movePeriods": [
      {
        "key": "1d",
        "label": "1d",
        "baseDate": "2026-07-16",
        "currentDate": "2026-07-17",
        "title": "短端上、长端下：扭转式走平",
        "baseValues": [
          4.16,
          4.28,
          4.57,
          5.09
        ],
        "summary": "2Y +2bp、5Y 0bp、10Y -2bp、30Y -3bp。前端仍保留政策利率尾部风险，避险买盘与实际利率回落则压低长端。",
        "detail": "油价先推高通胀补偿，但风险资产去拥挤和本周温和通胀数据压低真实折现率；因此长债获得买盘，曲线呈现短端微升、长端下行的扭转式走平。"
      },
      {
        "key": "7d",
        "label": "7d",
        "baseDate": "2026-07-10",
        "currentDate": "2026-07-17",
        "title": "短端领涨：牛市陡峭化",
        "baseValues": [
          4.21,
          4.3,
          4.56,
          5.06
        ],
        "summary": "2Y -3bp、5Y -2bp、10Y -1bp、30Y 0bp。收益率降幅集中在短端，长端几乎不动，曲线小幅陡峭化。",
        "detail": "一周维度看，市场略微下修近期政策利率路径，但油价、财政供给和期限溢价仍黏住长端；这更像短端宽松预期的局部回补，而非完整的长久期牛市。"
      },
      {
        "key": "30d",
        "label": "30d",
        "baseDate": "2026-06-17",
        "currentDate": "2026-07-17",
        "title": "短端下、长端上：扭转式陡峭化",
        "baseValues": [
          4.2,
          4.27,
          4.49,
          4.93
        ],
        "summary": "2Y -2bp、5Y +1bp、10Y +6bp、30Y +13bp。期限越长，收益率上行越明显，30s2s 显著变陡。",
        "detail": "过去一个月的核心不是 Fed path 全线上移，而是油价通胀风险、财政供给与 term premium 更集中地压向长端；这正是长久期资产相对短债承压的曲线证据。"
      },
      {
        "key": "6m",
        "label": "6m",
        "baseDate": "2026-01-16",
        "currentDate": "2026-07-17",
        "title": "全曲线上移：熊市走平",
        "baseValues": [
          3.59,
          3.82,
          4.24,
          4.83
        ],
        "summary": "2Y +59bp、5Y +46bp、10Y +31bp、30Y +23bp。全期限收益率上行，但短端升幅远大于长端。",
        "detail": "半年维度的主线是市场显著撤回近期降息定价，Fed path 重估强于长期期限溢价扩张。结果是债券整体下跌，同时 2Y 对 30Y 的利差明显收窄。"
      }
    ],
